import { searchCodebase } from '../indexer/dual-embedder.js';
import { scoreBatchTriton } from '../retrieval/triton-reranker.js';
import { bifrostChat } from '../ollama.js';
import { ENV } from '../env.server.js';
import type { ResearchTopic } from './deep-research.js';

/**
 * Autonomous Research Refiner
 * 
 * Validates and refinements research topics generated by Deep Research.
 * Uses Triton batch-reranking to score topics against actual codebase facts.
 */

const REFINEMENT_MODEL = ENV.OLLAMA_CHAT_MODEL;
const EVIDENCE_THRESHOLD = 0.3;

export interface ValidationResult {
    topicId: string;
    evidenceScore: number;
    grounded: boolean;
    evidenceChunks: Array<{ path: string; snippet: string }>;
}

/**
 * Validates a batch of research topics using Triton reranking.
 * Performs a search for each topic and calculates an evidence score.
 */
export async function validateTopicsWithTriton(
    topics: ResearchTopic[]
): Promise<Map<string, ValidationResult>> {
    const results = new Map<string, ValidationResult>();
    
    // We process each topic in parallel for retrieval, but batch the reranking
    const validationTasks = topics.map(async (topic) => {
        const hits = await searchCodebase(topic.selfPrompt, { limit: 5 }).catch(() => []);
        
        if (hits.length === 0) {
            return {
                topicId: topic.id,
                evidenceScore: 0,
                grounded: false,
                evidenceChunks: []
            };
        }

        // Score the candidates using Triton batch reranker
        const docTexts = hits.map(h => h.chunk.content.slice(0, 512));
        const scores = await scoreBatchTriton(topic.selfPrompt, docTexts);
        
        const topScore = Math.max(...scores, 0);
        
        return {
            topicId: topic.id,
            evidenceScore: topScore,
            grounded: topScore >= EVIDENCE_THRESHOLD,
            evidenceChunks: hits.slice(0, 3).map((h, i) => ({
                path: String(h.chunk.path ?? h.chunk.relativePath ?? 'unknown'),
                snippet: h.chunk.content.slice(0, 200),
                score: scores[i] ?? 0
            }))
        };
    });

    const validated = await Promise.all(validationTasks);
    for (const v of validated) {
        results.set(v.topicId, v);
    }
    
    return results;
}

/**
 * Refines a list of topics by re-prompting the LLM with evidence context
 * for ungrounded or weak topics.
 */
export async function refineTopicPrompts(
    topics: ResearchTopic[],
    validations: Map<string, ValidationResult>
): Promise<ResearchTopic[]> {
    const refined: ResearchTopic[] = [];

    for (const topic of topics) {
        const v = validations.get(topic.id);
        
        // If already well-grounded, keep as is
        if (v && v.grounded) {
            refined.push({ ...topic, validated: true });
            continue;
        }

        // Low evidence (or missing evidence): Re-ground the topic
        // We provide the weak hits to the LLM and ask it to find a better "angle"
        // that actually exists in the provided file paths.
        const evidenceContext = v?.evidenceChunks.length 
            ? v.evidenceChunks.map(c => `- ${c.path}: "${c.snippet}..."`).join('\n')
            : 'No direct codebase hits found.';

        const refinementPrompt = `
You are a legal research grounding logic. 
A research topic was suggested, but its "selfPrompt" is too generic or hallucinated for the current codebase.

ORIGINAL TOPIC: ${topic.title}
CURRENT PROMPT: ${topic.selfPrompt}
CURRENT DISCOVERY (WEAK HITS):
${evidenceContext}

TASK:
Adjust the "selfPrompt" to be technically grounded in the REAL files and concepts listed above.
The new prompt should be a high-specificity query that a code-search engine can actually resolve.

Return ONLY the refined query string.
`.trim();

        try {
            const newPrompt = await bifrostChat(
                [{ role: 'user', content: refinementPrompt }],
                REFINEMENT_MODEL,
                { temperature: 0.3, maxTokens: 128 }
            );

            refined.push({
                ...topic,
                selfPrompt: newPrompt.trim() || topic.selfPrompt,
                validated: v?.evidenceScore ? v.evidenceScore > 0.1 : false, // Marked as "best attempt"
                evidenceScore: v?.evidenceScore
            });
        } catch {
            // Fallback to original
            refined.push(topic);
        }
    }

    return refined;
}
